krpano.cssstyles:
.m3d_panel {
	font-family: -apple-system, BlinkMacSystemFont, "Roboto", "Inter", "Segoe UI", sans-serif;
	padding: 6px 4px 4px 4px;
	color: #f8fafc;
	min-width: 220px;
	user-select: none;
	cursor: default !important;
}
.m3d_header {
	display: flex;
	align-items: center;
	justify-content: space-between;
	margin-bottom: 12px;
	padding: 0 4px 6px 4px;
	border-bottom: 1px solid rgba(255, 255, 255, 0.08);
	cursor: move !important;
}
.m3d_title_wrap {
	display: flex;
	align-items: center;
	gap: 8px;
}
.m3d_head_icon {
	width: 18px;
	height: 18px;
	fill: #F16A24;
	display: flex;
	align-items: center;
}
.m3d_title {
	font-size: 13px;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: 0.06em;
	color: #ffffff;
	line-height: 1;
}
.m3d_drag_badge {
	font-size: 10px;
	color: #64748b;
	padding: 2px 6px;
	background: rgba(255, 255, 255, 0.05);
	border-radius: 4px;
	font-weight: 500;
}

/* Segmented MUI Toggle Switch */
.m3d_toggle {
	display: flex;
	background: rgba(0, 0, 0, 0.35);
	border: 1px solid rgba(255, 255, 255, 0.08);
	border-radius: 12px;
	padding: 3px;
	gap: 4px;
	margin-bottom: 12px;
	box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.3);
}
.m3d_seg {
	flex: 1;
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 6px;
	padding: 8px 10px;
	border-radius: 9px;
	font-size: 13px;
	font-weight: 600;
	color: #94a3b8;
	cursor: pointer !important;
	text-decoration: none;
	transition: all 0.22s cubic-bezier(0.4, 0, 0.2, 1);
}
.m3d_seg:hover {
	color: #ffffff;
	background: rgba(255, 255, 255, 0.05);
	text-decoration: none;
}
.m3d_seg_active {
	background: linear-gradient(135deg, #FF7A00 0%, #EE4D2D 100%) !important;
	color: #ffffff !important;
	box-shadow: 0 3px 12px rgba(241, 106, 36, 0.45);
}
.m3d_seg_icon {
	width: 17px;
	height: 17px;
	fill: currentColor;
	display: inline-block;
	flex-shrink: 0;
}

/* MUI Action Buttons */
.m3d_btn_list {
	display: flex;
	flex-direction: column;
	gap: 8px;
}
.m3d_btn {
	display: flex;
	align-items: center;
	gap: 10px;
	background: rgba(255, 255, 255, 0.05);
	border: 1px solid rgba(255, 255, 255, 0.09);
	border-radius: 10px;
	padding: 9px 12px;
	cursor: pointer !important;
	transition: all 0.22s cubic-bezier(0.4, 0, 0.2, 1);
	text-decoration: none;
	color: #e2e8f0;
	font-size: 12.5px;
	font-weight: 600;
	position: relative;
	overflow: hidden;
}
.m3d_btn:hover {
	background: rgba(241, 106, 36, 0.18);
	border-color: rgba(241, 106, 36, 0.45);
	color: #ffffff;
	transform: translateY(-1px);
	box-shadow: 0 4px 14px rgba(241, 106, 36, 0.25);
	text-decoration: none;
}
.m3d_btn:active {
	transform: translateY(0);
	box-shadow: none;
}
.m3d_btn_active {
	background: rgba(241, 106, 36, 0.22) !important;
	border-color: #F16A24 !important;
	color: #ffffff !important;
	box-shadow: 0 3px 12px rgba(241, 106, 36, 0.35) !important;
}
.m3d_btn_icon_box {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 28px;
	height: 28px;
	background: rgba(255, 255, 255, 0.07);
	border-radius: 7px;
	flex-shrink: 0;
	transition: all 0.2s ease;
}
.m3d_btn:hover .m3d_btn_icon_box {
	background: #F16A24;
	color: #ffffff;
	box-shadow: 0 2px 8px rgba(241, 106, 36, 0.4);
}
.m3d_btn_active .m3d_btn_icon_box {
	background: #F16A24 !important;
	color: #ffffff !important;
	box-shadow: 0 2px 8px rgba(241, 106, 36, 0.5) !important;
}
.m3d_btn_icon {
	width: 16px;
	height: 16px;
	fill: currentColor;
}
.m3d_btn_save {
	background: rgba(241, 106, 36, 0.12);
	border-color: rgba(241, 106, 36, 0.25);
	color: #ff9d66;
}
.m3d_btn_save:hover {
	background: #F16A24;
	border-color: #F16A24;
	color: #ffffff;
}
.m3d_btn_save .m3d_btn_icon_box {
	background: rgba(241, 106, 36, 0.25);
	color: #ff8e4d;
}
.m3d_hint {
	font-size: 11px;
	color: #64748b;
	text-align: center;
	margin-top: 8px;
	padding-top: 6px;
	border-top: 1px dashed rgba(255, 255, 255, 0.08);
}

krpano.action:
var isMeasure = (krpano.tourMode === "measure");
var mType     = krpano.measureType || 1;
var segWalk   = isMeasure ? "m3d_seg" : "m3d_seg m3d_seg_active";
var segMeas   = isMeasure ? "m3d_seg m3d_seg_active" : "m3d_seg";

var btnPointsClass   = (isMeasure && mType === 1) ? "m3d_btn m3d_btn_active" : "m3d_btn";
var btnSurfacesClass = (isMeasure && mType === 2) ? "m3d_btn m3d_btn_active" : "m3d_btn";

// SVG Icons (Material UI / Material Design 3 Style)
var svgRulerHead = '<svg class="m3d_head_icon" viewBox="0 0 24 24"><path d="M21 6H3c-1.1 0-2 .9-2 2v8c0 1.1.9 2 2 2h18c1.1 0 2-.9 2-2V8c0-1.1-.9-2-2-2zm0 10H3V8h2v4h2V8h2v2h2V8h2v4h2V8h2v2h2V8h3v8z"/></svg>';
var svgWalk      = '<svg class="m3d_seg_icon" viewBox="0 0 24 24"><path d="M13.5 5.5c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zM9.8 8.9L7 23h2.1l1.8-8 2.1 2v6h2v-7.5l-2.1-2 .6-3C14.8 12 16.8 13 19 13v-2c-1.9 0-3.5-1-4.3-2.4l-1-1.6c-.4-.6-1-1-1.7-1-.3 0-.5.1-.8.1L6 8.3V13h2V9.6l1.8-.7"/></svg>';
var svgMeasure   = '<svg class="m3d_seg_icon" viewBox="0 0 24 24"><path d="M17.66 17.66l-1.41 1.41L4.22 7.05l1.41-1.41 12.03 12.02zm-4.24-9.9l1.41 1.41-1.41 1.41-1.41-1.41 1.41-1.41zm-2.83 2.83l1.41 1.41-1.41 1.41-1.41-1.41 1.41-1.41zm-2.83 2.83l1.41 1.41-1.41 1.41-1.41-1.41 1.41-1.41zM20.49 4.93L19.07 3.51a1.996 1.996 0 0 0-2.83 0L3.51 16.24a1.996 1.996 0 0 0 0 2.83l1.41 1.41a1.996 1.996 0 0 0 2.83 0L20.49 7.76a1.996 1.996 0 0 0 0-2.83z"/></svg>';
var svgPoints    = '<svg class="m3d_btn_icon" viewBox="0 0 24 24"><path d="M19.5 9.5c-1.03 0-1.9.62-2.29 1.5H6.79c-.39-.88-1.26-1.5-2.29-1.5C3.12 9.5 2 10.62 2 12s1.12 2.5 2.5 2.5c1.03 0 1.9-.62 2.29-1.5h10.42c.39.88 1.26 1.5 2.29 1.5 1.38 0 2.5-1.12 2.5-2.5s-1.12-2.5-2.5-2.5z"/></svg>';
var svgSurfaces  = '<svg class="m3d_btn_icon" viewBox="0 0 24 24"><path d="M9.01 14H2v2h7.01v3L13 15l-3.99-4v3zm5.98-1v-3H22V8h-7.01V5L11 9l3.99 4z"/></svg>';
var svgSave      = '<svg class="m3d_btn_icon" viewBox="0 0 24 24"><path d="M17 3H5c-1.11 0-2 .9-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2V7l-4-4zm2 16H5V5h11.17L19 7.83V19zm-7-7c-1.66 0-3 1.34-3 3s1.34 3 3 3 3-1.34 3-3-1.34-3-3-3zM6 6h9v4H6z"/></svg>';

var html = ""
	+ '<div class="m3d_panel">'
	+   '<div class="m3d_header">'
	+     '<div class="m3d_title_wrap">'
	+       svgRulerHead
	+       '<span class="m3d_title">Th\u01b0\u1edbc \u0110o 3D</span>'
	+     '</div>'
	+     '<div class="m3d_drag_badge">\u2756</div>'
	+   '</div>'
	+   '<div class="m3d_toggle">'
	+     '<a class="' + segWalk + '" href="event:m3d_mode_walk()">'
	+       svgWalk + '<span>\u0110i</span>'
	+     '</a>'
	+     '<a class="' + segMeas + '" href="event:m3d_mode_measure()">'
	+       svgMeasure + '<span>\u0110o</span>'
	+     '</a>'
	+   '</div>';

if (isMeasure) {
	html += '<div class="m3d_btn_list">'
		+   '<a class="' + btnPointsClass + '" href="event:start_measuring_between_points(true)">'
		+     '<div class="m3d_btn_icon_box">' + svgPoints + '</div>'
		+     '<span>\u0110o gi\u1eefa 2 \u0111i\u1ec3m</span>'
		+   '</a>'
		+   '<a class="' + btnSurfacesClass + '" href="event:start_measuring_between_surfaces(true)">'
		+     '<div class="m3d_btn_icon_box">' + svgSurfaces + '</div>'
		+     '<span>\u0110o gi\u1eefa 2 b\u1ec1 m\u1eb7t</span>'
		+   '</a>'
		+   '<a class="m3d_btn m3d_btn_save" href="event:save_measurements()">'
		+     '<div class="m3d_btn_icon_box">' + svgSave + '</div>'
		+     '<span>L\u01b0u s\u1ed1 \u0111o</span>'
		+   '</a>'
		+ '</div>'
		+ '<div class="m3d_hint">Double-click \u0111\u1ec3 ch\u1ecdn \u0111i\u1ec3m \u0111o \u2022 ESC \u0111\u1ec3 hu\u1ef7</div>';
}
html += '</div>';

if (krpano.get("layer[measure3d_ui]")) {
	krpano.set("layer[measure3d_ui].html", html);
}

var measure3d = krpano.measure3d;

if(measure3d.ui)
{
	var ui = krpano.addlayer("measure3d_ui");

	var ui_pos = measure3d.ui_pos.split(",");

	ui.setvars({
		keep:true,
		type:"text",
		align:ui_pos[0], x:ui_pos[1], y:ui_pos[2],
		css:"color:white;",
		bgcolor:0x0f172a,
		bgalpha:0.85,
		bgborder:"1 0xffffff 0.12",
		bgroundedge:14,
		bgshadow:"0 12px 36px rgba(0,0,0,0.45)",
		cursor:"default",
		// Chan click xuyen qua panel xuong 360: layer nuot toan bo su kien chuot.
		capture:true,
		bgcapture:true,
		padding:"12 12"
	});

	// make the layer dragable
	if (measure3d.ui_dragable)
	{
	 	ui.cursor = "move";
		ui.ondown = "changealign(lefttop); asyncloop(pressed, x+=mouse.dx; y+=mouse.dy; clamp(x,0,calc(stagewidth-pixelwidth)); clamp(y,0,calc(stageheight-pixelheight)); );";
	}

	// Danh dau con tro dang o tren panel de handler click & mouse_pos cua 360 bo qua
	ui.onover = function() { krpano.overMeasureUI = true; };
	ui.onout  = function() { krpano.overMeasureUI = false; };

	// Mac dinh o che do "Di" (walk) va phan loai do 2 diem (type 1)
	krpano.tourMode = "walk";
	krpano.measureType = 1;
	krpano.call("m3d_render_ui()");
}

krpano.measureType = 1;
if (krpano.measure3d_loop === true && krpano.tourMode === "measure")
{
	if (window.m3d_cleanup_draft) { window.m3d_cleanup_draft(); }
	if (showinfo) { measure3d_showinfo('double click to start/stop measuring'); }
	krpano.call("m3d_render_ui()");
}
else
{
	if (showinfo) { measure3d_showinfo('double click to start/stop measuring'); }
	measure3d_start(1);
}

krpano.measureType = 2;
if (krpano.measure3d_loop === true && krpano.tourMode === "measure")
{
	if (window.m3d_cleanup_draft) { window.m3d_cleanup_draft(); }
	if (showinfo) { measure3d_showinfo('double click to measure surface'); }
	krpano.call("m3d_render_ui()");
}
else
{
	if (showinfo) { measure3d_showinfo('double click to measure surface'); }
	measure3d_start(2);
}

krpano.measure3d_loop = false;
if (window.m3d_cleanup_draft) { window.m3d_cleanup_draft(); }

// Bat lai dieu huong cua plugin navigator sau khi ket thuc do.
krpano.jyNavEnabled = false;
krpano.get("events").ondoubleclick = null;

krpano.hotspot.forEach(function(h) {
	var style = h.style || "";
	var name = h.name || "";
	var isMeasureHS = (typeof style === "string" && style.indexOf("measure3d") > -1) || 
	                  (typeof name === "string" && name.indexOf("measure3d") > -1);
	if (!isMeasureHS) {
		h.enabled = true;
	}
});

// Tro ve che do Di va cap nhat giao dien toggle.
krpano.tourMode = "walk";
krpano.call("m3d_render_ui()");

var xmlcode = '';
krpano.hotspot.forEach( function(hs)
{
	if(hs.style == 'measure3d_line' || hs.style == 'measure3d_linetext' || hs.style == 'measure3d_marker')
	{
		xmlcode += hs.getxml() + "\n";
	}
});

navigator.clipboard.writeText(xmlcode);

krpano.call("measure3d_showinfo('the measurement xml code[br]was copied to the clipboard');");

addlayer('measure3d_infotext',l);
set(l, type=text, html=get(infotext), css='font-size:18px;font-weight:bold;color:white;text-align:center', bg=false, txtshadow='0 1 4 0x000000 1.0', align=center, enabled=false, alpha=0, width=50%);
tween(l.alpha, 1.0);
delayedcall(3.0,
	tween(l.alpha, 0.0, 0.25, default, removelayer(get(l.name)); );
);


var measure3d = krpano.measure3d;
var gap = measure3d.gap;

var mode = 1*args[1];
krpano.measureType = mode;

// Vô hiệu hóa các hotspot di chuyển khi đo đạc
krpano.hotspot.forEach(function(h) {
	var style = h.style || "";
	var name = h.name || "";
	var isMeasureHS = (typeof style === "string" && style.indexOf("measure3d") > -1) || 
	                  (typeof name === "string" && name.indexOf("measure3d") > -1);
	if (!isMeasureHS) {
		h.enabled = false;
	}
});

// Chan dieu huong cua plugin "navigator" (forward-sensing) khi dang do.
krpano.jyNavEnabled = true;

// Danh dau dang o che do Do va cap nhat giao dien toggle.
krpano.tourMode = "measure";
krpano.call("m3d_render_ui()");

var hs = krpano.addhotspot("auto", "webgl");
hs.loadstyle("measure3d_cursor");

var line = null;
var line_p1 = null;
var line_p2 = null;
var p1marker = null;
var p2marker = null;

window.m3d_cleanup_draft = function() {
	if (line) { line.remove(); line = null; }
	if (p1marker) { p1marker.remove(); p1marker = null; }
	if (p2marker) { p2marker.remove(); p2marker = null; }
	line_p1 = null;
	line_p2 = null;
};

krpano.events.ondoubleclick = function()
{
	// Khong thuc hien ve neu chuot dang nam tren UI
	if (krpano.overMeasureUI) {
		return;
	}

	var currentMode = krpano.measureType || 1;
	var hit = null;

	if (line == null)
	{
		line = krpano.addhotspot("auto", "webgl");
		line.loadstyle("measure3d_line");

		line_p1 = line.point.createItem(0);
		line_p2 = line.point.createItem(1);
		line_p1.x = line_p2.x = hs.tx;
		line_p1.y = line_p2.y = hs.ty;
		line_p1.z = line_p2.z = hs.tz;

		p1marker = krpano.addhotspot("auto", "webgl");
		p1marker.loadstyle("measure3d_marker");
		p1marker.tx = line_p1.x;
		p1marker.ty = line_p1.y;
		p1marker.tz = line_p1.z;
		p1marker.rx = hs.rx;
		p1marker.ry = hs.ry;
		p1marker.rz = hs.rz;

		if (currentMode == 2)
		{
			hit = krpano.raycast(hs.tx, hs.ty, hs.tz, hs.nx, hs.ny, hs.nz);
			if (hit)
			{
				line_p2.x = hit.x;
				line_p2.y = hit.y;
				line_p2.z = hit.z;
			}
			else
			{
				krpano.call("measure3d_showinfo('no hit')");
				p1marker.remove();
				line.remove();
				line = null;
				p1marker = null;
				return;
			}
		}
		else
		{
			return;
		}
	}

	// finish
	var dx = line_p2.x - line_p1.x;
	var dy = line_p2.y - line_p1.y;
	var dz = line_p2.z - line_p1.z;
	var length = Math.sqrt(dx*dx + dy*dy + dz*dz);

	var lineinfo = krpano.addhotspot("auto", "webgl");
	lineinfo.loadstyle("measure3d_linetext");

	krpano.v = length;
	krpano.actions.calc("v_formated", measure3d.unit_format);
	lineinfo.html = krpano.v_formated;

	if (measure3d.showslope)
	{
		var y_angle = Math.atan2(-dy, Math.sqrt(dx*dx + dz*dz) ) / Math.PI * 180.0;

		lineinfo.html += "[br]" + Math.abs(y_angle).toFixed(2) + "°";
	}


	lineinfo.deletehtml = "[span style='font-size:18px;color:red;vertical-align:middle;']❌[/span] Delete";

	// place between the points
	lineinfo.tx = 0.5*line_p1.x + 0.5*line_p2.x;
	lineinfo.ty = 0.5*line_p1.y + 0.5*line_p2.y;
	lineinfo.tz = 0.5*line_p1.z + 0.5*line_p2.z;

	lineinfo.onclick = function()
	{
		if (lineinfo.backuphtml)
		{
			lineinfo.hs_line.remove();
			lineinfo.hs_p1marker.remove();
			lineinfo.hs_p2marker.remove();
			lineinfo.remove();
		}
		else
		{
			lineinfo.backuphtml = lineinfo.html;
			lineinfo.html = lineinfo.deletehtml;

			krpano.actions.delayedcall(1, function()
			{
				if (lineinfo.backuphtml)
				{
					lineinfo.html = lineinfo.backuphtml
					lineinfo.backuphtml = null;
				}
			});
		}
	}

	if (krpano.device.mouse)
	{
		lineinfo.onover = function()
		{
			if (!lineinfo.backuphtml)
			{
				lineinfo.backuphtml = lineinfo.html;
				lineinfo.html = lineinfo.deletehtml;
			}
		}

		lineinfo.onout = function()
		{
			if (lineinfo.backuphtml)
			{
				lineinfo.html = lineinfo.backuphtml;
				lineinfo.backuphtml = null;
			}
		}
	}

	p2marker = krpano.addhotspot("auto", "webgl");
	p2marker.loadstyle("measure3d_marker");
	p2marker.tx = line_p2.x;
	p2marker.ty = line_p2.y;
	p2marker.tz = line_p2.z;

	p2marker.rx = (hit || hs).rx;
	p2marker.ry = (hit || hs).ry;
	p2marker.rz = (hit || hs).rz;

	lineinfo.hs_line = line;
	lineinfo.hs_p1marker = p1marker;
	lineinfo.hs_p2marker = p2marker;

	// Giu lai so do khi chuyen scene (cac scene dung chung he toa do 3D).
	line.keep = true;
	p1marker.keep = true;
	p2marker.keep = true;
	lineinfo.keep = true;

	line = null;
	line_p1 = null;
	line_p2 = null;
	p1marker = null;
	p2marker = null;

	if (krpano.device.touch)
	{
		// stop after drawing one line on touch devices
		krpano.call("stop_measuring();");
	}
}

krpano.measure3d_loop = true;

krpano.actions.asyncloop("measure3d_loop",
	function()
	{
		if (krpano.overMeasureUI)
		{
			hs.visible = false;
			return;
		}

		var hit = null;

		if (krpano.hoveringelement == null || krpano.hoveringelement == hs || (krpano.hoveringelement && krpano.hoveringelement.hittest))
		{
			hit = krpano.cursorraycast();
		}

		if (hit)
		{
			// optionally add a small gap/offset to the hit surface to avoid depthbuffer rendering problems
			hs.tx = hit.x + hit.nx*gap;
			hs.ty = hit.y + hit.ny*gap;
			hs.tz = hit.z + hit.nz*gap;

			// hotspot rotation
			hs.rx = hit.rx;
			hs.ry = hit.ry;
			hs.rz = hit.rz;

			// store also the normal of the hit-surface for later usage
			hs.nx = hit.nx;
			hs.ny = hit.ny;
			hs.nz = hit.nz;

			hs.visible = true;

			if (line)
			{
				line.visible = true;
			}

			if (line_p2)
			{
				line_p2.x = hs.tx;
				line_p2.y = hs.ty;
				line_p2.z = hs.tz;
			}
		}
		else
		{
			if (line)
			{
				line.visible = false;
			}

			hs.visible = false;
		}
	},
	function()
	{
		if(line) line.remove();
		if(p1marker) p1marker.remove();
		hs.remove();
	}
);
